    float el = easu_luma(e);
    float fl = easu_luma(f);
    float gl = easu_luma(g);
    float hl = easu_luma(h);
    float il = easu_luma(i);
    float jl = easu_luma(j);
    float kl = easu_luma(k);
    float ll = easu_luma(l);
    float nl = easu_luma(n);
